using System;

// PROGRAM: Pembuktian Ilmiah Double vs Decimal pada Kasus Finansial
Console.WriteLine("=== EKSPERIMEN FLOATING POINT IEEE 754 ===");

// 1. Menggunakan DOUBLE (Floating Point Biner)
double saldoDouble = 0.0;
for (int i = 0; i < 10; i++)
{
    saldoDouble += 0.1;
}
Console.WriteLine($"Hasil akumulasi 10 x 0.1 dengan DOUBLE : {saldoDouble:R}");
Console.WriteLine($"Apakah tepat sama dengan 1.0? : {saldoDouble == 1.0}");

// 2. Menggunakan DECIMAL (Base-10 Fixed Precision)
decimal saldoDecimal = 0.0m;
for (int i = 0; i < 10; i++)
{
    saldoDecimal += 0.1m;
}
Console.WriteLine($"\nHasil akumulasi 10 x 0.1 dengan DECIMAL: {saldoDecimal}");
Console.WriteLine($"Apakah tepat sama dengan 1.0m?: {saldoDecimal == 1.0m}");

