using System;

public class FinancialInterestCalculator
{
    public static decimal CalculateSimpleInterest(decimal saldoAwal, decimal bungaPersenTahunan, int durasiBulan)
    {
        if (saldoAwal <= 0 || bungaPersenTahunan <= 0 || durasiBulan <= 0)
            return 0m;

        decimal interestRate = bungaPersenTahunan / 100m;
        decimal timeInYears = (decimal)durasiBulan / 12m;
        decimal totalInterest = saldoAwal * interestRate * timeInYears;
        decimal totalAmount = saldoAwal + totalInterest;

        return Math.Round(totalAmount, 2, MidpointRounding.AwayFromZero);
    }

    public static void Main()
    {
        Console.WriteLine(CalculateSimpleInterest(1000000m, 12m, 6));
    }
}
